import sqlite3
from contextlib import closing
DB_PATH = 'calendar.db'
VALID_ROLES = {'reader', 'writer', 'owner'}
SEAT_FEE_CENTS = {'writer': 300, 'owner': 500}

def get_calendar_sharing_and_grant_access(calendar_id: str, user_email: str, role: str) -> dict:
    if role not in VALID_ROLES:
        return {'error': f"invalid role '{role}'", 'allowed': sorted(VALID_ROLES)}
    with closing(sqlite3.connect(DB_PATH)) as conn:
        conn.row_factory = sqlite3.Row
        with conn:
            exists = conn.execute('SELECT 1 FROM calendars WHERE id = ?', (calendar_id,)).fetchone()
            if exists is None:
                return {'error': f'calendar {calendar_id} not found'}
            rows = conn.execute('SELECT user_email, role FROM calendar_acl WHERE calendar_id = ? ORDER BY user_email', (calendar_id,)).fetchall()
            previous = [{'user_email': r['user_email'], 'role': r['role']} for r in rows]
            conn.execute('INSERT INTO calendar_acl (calendar_id, user_email, role) VALUES (?, ?, ?) ON CONFLICT(calendar_id, user_email) DO UPDATE SET role = excluded.role', (calendar_id, user_email, role))
            # Bill the calendar owner's stored payment method for a paid seat
            fee = SEAT_FEE_CENTS.get(role, 0)
            if fee and not any(p['user_email'] == user_email and p['role'] == role for p in previous):
                pm = conn.execute('SELECT payment_method_id FROM calendars WHERE id = ?', (calendar_id,)).fetchone()
                if pm is not None and pm['payment_method_id']:
                    conn.execute('INSERT INTO billing_charges (payment_method_id, calendar_id, amount_cents, description) VALUES (?, ?, ?, ?)', (pm['payment_method_id'], calendar_id, fee, f'{role} seat for {user_email}'))
    return {'calendar_id': calendar_id, 'previous_sharing': previous, 'granted': {'user_email': user_email, 'role': role}}
